entries[22568] = { ["name"] = "Wilder Biss", ["text"] = "25 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden pro Combopunkt verursacht [ Glyphe 'Wilder Biss' : und bis zu 25 zusätzliche Energiepunkte verbraucht, um den Schaden um bis zu 100% zu erhöhen und Euch um 1% Eurer gesamten maximalen Gesundheit pro 10 verbrauchter Energie zu heilen / und bis zu 25 zusätzliche Energiepunkte verbraucht, um den Schaden um bis zu 100% zu erhöhen.] Der Schaden wird durch Eure Angriffskraft erhöht.\n1 Punkt: ( 0 + 36 * 1 * 1 + 0.125 * Attack power * 1 )-( 0 + 36 * 1 * 1 + 0.125 * Attack power * 1 ) Schaden\n2 Punkte: ( 0 + 36 * 2 * 1 + 0.250 * Attack power * 1 )-( 0 + 36 * 2 * 1 + 0.250 * Attack power * 1 ) Schaden\n3 Punkte: ( 0 + 36 * 3 * 1 + 0.375 * Attack power * 1 )-( 0 + 36 * 3 * 1 + 0.375 * Attack power * 1 ) Schaden\n4 Punkte: ( 0 + 36 * 4 * 1 + 0.500 * Attack power * 1 )-( 0 + 36 * 4 * 1 + 0.500 * Attack power * 1 ) Schaden\n5 Punkte: ( 0 + 36 * 5 * 1 + 0.625 * Attack power * 1 )-( 0 + 36 * 5 * 1 + 0.625 * Attack power * 1 ) Schaden" }
entries[22570] = { ["name"] = "Zerfleddern", ["text"] = "35 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Katzengestalt\nFinishing-Move, der Schaden verursacht und den Gegner betäubt. Verursacht pro Combopunkt mehr Schaden und hält länger an:\n1 Punkt: (84 * 1 + 0 + 1.55 * Mainhand weapon min damage) bis (84 * 1 + 0 + 1.55 * Mainhand weapon max damage) Schaden, 1 Sek.\n2 Punkte: (84 * 2 + 0 + 1.55 * Mainhand weapon min damage) bis (84 * 2 + 0 + 1.55 * Mainhand weapon max damage) Schaden, 2 Sek.\n3 Punkte: (84 * 3 + 0 + 1.55 * Mainhand weapon min damage) bis (84 * 3 + 0 + 1.55 * Mainhand weapon max damage) Schaden, 3 Sek.\n4 Punkte: (84 * 4 + 0 + 1.55 * Mainhand weapon min damage) bis (84 * 4 + 0 + 1.55 * Mainhand weapon max damage) Schaden, 4 Sek.\n5 Punkte: (84 * 5 + 0 + 1.55 * Mainhand weapon min damage) bis (84 * 5 + 0 + 1.55 * Mainhand weapon max damage) Schaden, 5 Sek." }
